const output = [];

for (const [itemIndex, item] of $input.all().entries()) {
  // Handles either flat fields or a nested documents object.
  const doc = item.json.documents ?? item.json;

  if (!doc.source_id || typeof doc.text !== "string") {
    throw new Error(`Missing source_id or text in item ${itemIndex}`);
  }

  const sentences = doc.text.trim().split(/(?<=[.!?])\s+/);
  let buffer = [];
  let chunkNumber = 0;

  function saveChunk() {
    chunkNumber++;
    const text = buffer.join(" ");

    output.push({
      json: {
        chunk_id: `${doc.source_id}-chunk-${chunkNumber}`,
        source_id: doc.source_id,
        title: doc.title,
        type: doc.type,
        language: doc.language,
        synthetic: doc.synthetic,
        chunk_number: chunkNumber,
        text,
        embedding_text: `${doc.title}\n${text}`
      },
      pairedItem: { item: itemIndex }
    });
  }

  for (const sentence of sentences) {
    if (buffer.length && [...buffer, sentence].join(" ").length > 900) {
      saveChunk();
      // Carry the last sentence into the next chunk.
      buffer = buffer.length > 1 ? [buffer[buffer.length - 1]] : [];
    }
    buffer.push(sentence);
  }

  if (buffer.length) saveChunk();
}

return output;

const vectors = $input.all().map((item, index) => {
  const chunk = $("Create Chunks").itemMatching(index).json;
  const values = item.json.data?.[0]?.embedding;

  if (!Array.isArray(values) || values.length !== 1536) {
    throw new Error(`Expected 1536 embedding values for item ${index}`);
  }

  return {
    id: chunk.chunk_id,
    values,
    metadata: {
      source_id: chunk.source_id,
      title: chunk.title,
      type: chunk.type,
      language: chunk.language,
      synthetic: chunk.synthetic,
      chunk_number: chunk.chunk_number,
      text: chunk.text
    }
  };
});

return [{
  json: {
    namespace: "kb-v1",
    vectors
  }
}];

const vectors = $input.all().map((item, index) => {
  const chunk = $("Create Chunks").itemMatching(index).json;
  const embedding = item.json.data?.[0];

  const indices = embedding?.sparse_indices;
  const values = embedding?.sparse_values;

  if (
    !Array.isArray(indices) ||
    !Array.isArray(values) ||
    indices.length === 0 ||
    indices.length !== values.length
  ) {
    throw new Error(`Invalid sparse embedding for item ${index}`);
  }

  return {
    id: chunk.chunk_id,
    sparseValues: {
      indices,
      values
    },
    metadata: {
      source_id: chunk.source_id,
      title: chunk.title,
      type: chunk.type,
      language: chunk.language,
      synthetic: chunk.synthetic,
      chunk_number: chunk.chunk_number,
      text: chunk.text
    }
  };
});

return [{
  json: {
    namespace: "kb-v1",
    vectors
  }
}];
